// ARCHITECT-2525 / FUTURE · domain/geometry — the locked V2 physical schema (plan §7, FCRS-06/07).
// 12 ft outer / 10 ft clear / 1 ft reserved perimeter wall-service zone, integer micrometres, right-handed
// datum (+X East, +Y North, +Z Up). These are FUTURE truths, regenerated by the V1→V2 transformation — NEVER
// copied from the legacy 10-ft seed. Node strip-types: const + union + interface only.

/** 1 ft = 304,800 µm (matches donor canonical/units.ts; re-declared here so Future owns its own constant). */
export const UM_PER_FT = 304_800;
export const CLEAR_UM = 3_048_000;              // 10 ft clear room
export const ZONE_UM = 304_800;                 // 1 ft reserved perimeter wall/service zone, each side
export const OUTER_UM = CLEAR_UM + 2 * ZONE_UM; // 3,657,600 µm = 12 ft outer module
export const STOREY_UM = 3_048_000;             // 10 ft clear ceiling (ASSUMED)

/** The reference transformation profile id (plan §11). */
export const PROFILE_ID = "REFERENCE_3X3_12_10_1" as const;

export const SPACE_FUNCTIONS = [
  "BEDROOM", "BATH", "CLOSET", "LIVING", "KITCHEN", "DINING", "OFFICE", "UTILITY", "ENTRY",
] as const;
export type SpaceFunction = (typeof SPACE_FUNCTIONS)[number];

export const WET_CLASSES = ["WET", "DRY"] as const;
export type WetClass = (typeof WET_CLASSES)[number];

/**
 * A rectangular Space (plan §7). Outer AND clear are explicit, plus the reserved zone — so the service zone
 * can never be confused with a structural wall (plan §8). Invariant: outer = clear + 2·zone (both axes).
 */
export interface SpaceEntityV2 {
  entity_id: string;
  entity_type: "SPACE";
  bay_code: string;            // A1…C3, the human handle
  outer_x_um: number;          // SW corner of the outer module, on the permanent datum
  outer_y_um: number;
  z_um: number;
  outer_width_um: number;
  outer_depth_um: number;
  clear_width_um: number;
  clear_depth_um: number;
  wall_zone_thickness_um: number;
  function: SpaceFunction;
  wet_class: WetClass;
}

/** The locked reference figures, DERIVED from the 3×3 of 12-ft modules (plan §7). */
export const REFERENCE_GRID = 3;
export const SHELL_FT = REFERENCE_GRID * (OUTER_UM / UM_PER_FT);     // 36 ft
export const GROSS_FT2 = SHELL_FT * SHELL_FT;                        // 1,296 ft²
export const CLEAR_FT2 = REFERENCE_GRID * REFERENCE_GRID * (CLEAR_UM / UM_PER_FT) * (CLEAR_UM / UM_PER_FT); // 900 ft²
export const DIFFERENCE_FT2 = GROSS_FT2 - CLEAR_FT2;                 // 396 ft²

/** µm → ft (render/edit boundary converts once; canonical stays integer µm). */
export function ftFromUm(um: number): number { return um / UM_PER_FT; }
export function umFromFt(ft: number): number { return Math.round(ft * UM_PER_FT); }

/** The §8 invariant: outer = clear + 2·zone on both axes, with the locked reference values. */
export function geometryOk(s: SpaceEntityV2): boolean {
  return (
    s.outer_width_um === s.clear_width_um + 2 * s.wall_zone_thickness_um &&
    s.outer_depth_um === s.clear_depth_um + 2 * s.wall_zone_thickness_um &&
    s.clear_width_um === CLEAR_UM && s.clear_depth_um === CLEAR_UM &&
    s.wall_zone_thickness_um === ZONE_UM &&
    s.outer_width_um === OUTER_UM && s.outer_depth_um === OUTER_UM
  );
}
